// ── Module registry (WORKFLOW-SPEC §2) ──────────────────────────────────────
// Record modules support Create/Update/Archive/Get/Get Many; functional areas provide actions only.
const RECORD_MODULES = [
  { id:"request",        label:"Request",        recordTypes:["Incident","Service Request"] },
  { id:"problem",        label:"Problem" },
  { id:"change",         label:"Change" },
  { id:"release",        label:"Release" },
  { id:"hardware_asset", label:"Hardware Asset" },
  { id:"software_asset", label:"Software Asset" },
  { id:"nonit_asset",    label:"Non-IT Asset" },
  { id:"cmdb",           label:"CMDB (CI)" },
  { id:"asset_movement", label:"Asset Movement" },
  { id:"user",           label:"User" },
  { id:"task",           label:"Task" },
  { id:"announcement",   label:"Announcement" },
  { id:"deployment",     label:"Deployment" },
];
const FUNCTIONAL_AREAS = [
  { id:"approval",     label:"Approval" },
  { id:"notification", label:"Notification" },
  { id:"http",         label:"Http Request" },
  { id:"plugin",       label:"Plugin" },
];
const moduleDef  = (id) => RECORD_MODULES.find(m=>m.id===id) || FUNCTIONAL_AREAS.find(m=>m.id===id);
const moduleByLabel = (label) => RECORD_MODULES.find(m=>m.label===label);
// trigger {module} slot: a record event can target any record module OR a specific record type (Incident / Service Request)
const MODULE_NAMES = RECORD_MODULES.flatMap(m => m.recordTypes ? m.recordTypes : [m.label]);
const MODULES   = MODULE_NAMES; // back-compat alias used by trigger slots
// TRIGGER module options ALSO offer the COMBINED parent (e.g. "Request" = Incident + Service Request) so one
// trigger can target BOTH record types at once — instead of building the same rule twice. When "Request" is
// chosen, downstream condition catalogs MERGE both types (see conditionFieldsFor). Create/Get stay record-type-
// specific (MODULE_NAMES) — you can't create a generic "Request". (user 2026-07-22)
const TRIGGER_MODULES = RECORD_MODULES.flatMap(m => m.recordTypes ? [m.label, ...m.recordTypes] : [m.label]);
// map a chosen trigger module-name (e.g. "Incident", "Problem") back to its record-module id
const moduleIdFromName = (name) => {
  if (!name) return null;
  const rt = RECORD_MODULES.find(m => m.recordTypes && m.recordTypes.includes(name));
  if (rt) return rt.id;
  const m = RECORD_MODULES.find(m => m.label===name);
  return m ? m.id : null;
};
