// The linear builder no longer has an inline CHECK IF — convert any in the samples to an IF / Else whose IF path
// holds the steps the inline check used to gate (ELSE starts empty).
(function inlineToIfElse(){
  const conv = (nodes) => { const out=[]; for (let j=0;j<(nodes||[]).length;j++){ const n = fix(nodes[j]);
      if (n.kind==="condition") { out.push({ id:n.id, kind:"branch", ifelse:true,
          paths:[{ id:n.id+"_if", combiner:n.combiner||"and", clauses:(n.clauses||[]).map((c,ci)=>{ const {or, ...r}=c; return ci>0 ? { ...r, conn: or ? "or" : (r.conn||"and") } : r; }), children:conv(nodes.slice(j+1)) },
                 { id:n.id+"_else", isElse:true, combiner:"and", clauses:[], children:[] }],
          otherwise:null }); return out; }
      out.push(n); } return out; };
  const fix = (n) => { const m = { ...n };
    if (m.paths) m.paths = m.paths.map(p => ({ ...p, children:conv(p.children) }));
    if (m.otherwise) m.otherwise = { ...m.otherwise, children:conv(m.otherwise.children) };
    if (m.success) m.success = { ...m.success, children:conv(m.success.children) };
    if (m.children) m.children = conv(m.children);
    return m; };
  Object.keys(USECASE_DOCS).forEach(k => { const d = USECASE_DOCS[k]; if (d && d.flow) d.flow = conv(d.flow); });
})();
