// trigger picker contents (matches the "When this happens" design)
const RECORD_EVENT_ITEMS = [
  { header:"Record events" },
  { id:"created", label:"When a record is created", icon:I.plus,   keywords:"create new add raise log open" },
  { id:"changed", label:"When a record is updated", icon:I.field,  keywords:"update change modify edit field value" },
  { id:"archived", label:"When a record is archived", icon:I.field, keywords:"archive delete remove retire close" },
];
const TIME_ONCE = { id:"once", label:"Once", icon:I.cal, keywords:"once one time single run date schedule when specific" };
// the "Every time period" cadences — a DRILL-IN sub-menu when browsing (user 2026-07-10: "just show Once or Every
// time period; selecting Every time period shows hourly/daily/weekly/monthly"), but flat & searchable directly.
const PERIOD_CADENCES = [
  { id:"hourly",  label:"Hourly",  icon:I.repeat, keywords:"hourly every hour periodic schedule recurring repeat" },
  { id:"daily",   label:"Daily",   icon:I.repeat, keywords:"daily every day periodic schedule recurring repeat" },
  { id:"weekly",  label:"Weekly",  icon:I.repeat, keywords:"weekly every week periodic schedule recurring repeat monday" },
  { id:"monthly", label:"Monthly", icon:I.repeat, keywords:"monthly every month periodic schedule recurring repeat" },
];
// BROWSE = Record events + Time based(Once, Every time period ▸ drill). FLAT (search) expands the drill so typing
// "daily"/"weekly" jumps straight to the cadence.
const TRIGGER_MENU = [ ...RECORD_EVENT_ITEMS, { header:"Time based" }, TIME_ONCE,
  { id:"__period", label:"Every time period", icon:I.repeat, drill:true, keywords:"periodic period schedule recurring repeat hourly daily weekly monthly every cron interval" } ];
const TRIGGER_MENU_FLAT = [ ...RECORD_EVENT_ITEMS, { header:"Time based" }, TIME_ONCE, ...PERIOD_CADENCES ];

// ── Dynamic MODULE SEARCH in the trigger picker (2026-07-10) ────────────────────
// The trigger picker is the MERGED model: you pick a generic EVENT ("When a record
// is created") then fill the MODULE as a slot. That's easy for new users, but
// existing users still SEARCH the module name ("incident") and find nothing (the
// rows are generic). This is an ADDITIVE search layer — the merged model underneath
// is unchanged. Typing a module name morphs the `record` word into that module
// across the event rows ("When an Incident is created / …updated / …archived"),
// typeahead-highlighting the match; picking a row PRE-FILLS the module slot. For a
// small KNOWN family ("asset" → Hardware / Software / Non-IT; "request" → Incident /
// Service Request) an inline chooser fills the SLOT instead of multiplying rows.
const TRIGGER_EVENTS = [
  { id:"created",  icon:I.plus,  tail:"is created",  verbs:["create","created","creates","new","add","added","raise","raised","log","logged","open","opened"] },
  { id:"changed",  icon:I.field, tail:"is updated",  verbs:["update","updated","updates","change","changed","changes","modify","modified","edit","edited"] },
  { id:"archived", icon:I.field, tail:"is archived", verbs:["archive","archived","archives","delete","deleted","remove","removed","retire","retired"] },
];
// cohesive families whose members share a base word → an inline chooser, never extra rows. `min` = the
// shortest prefix that fires it (asset can fire at "as"; request waits for "req" so "re" still finds Release).
const MODULE_FAMILIES = [
  { key:"asset",   label:"Which asset?",   min:2, aliases:["asset","assets"],
    options:[{short:"Hardware", module:"Hardware Asset"},{short:"Software", module:"Software Asset"},{short:"Non-IT", module:"Non-IT Asset"}] },
  { key:"request", label:"Which request?", min:3, aliases:["request","requests"],
    options:[{short:"Incident", module:"Incident"},{short:"Service Request", module:"Service Request"}] },
];
// "a" / "an" by SOUND, not just the letter — "User" is a vowel letter but a consonant sound ("a User").
// common everyday synonyms per module → so "ticket" finds Incident, "device" finds Hardware Asset, etc. Fed
// into both the trigger morph and the action Create rows so search reflects how people actually talk.
const MODULE_SYNONYMS = {
  "Incident":"ticket issue outage",
  "Service Request":"request sr service ticket",
  "Problem":"rca root cause",
  "Change":"cr rfc",
  "Release":"deploy rollout",
  "Hardware Asset":"device machine laptop desktop server",
  "Software Asset":"license application app",
  "Non-IT Asset":"facility equipment",
  "CMDB (CI)":"ci configuration item service",
  "Asset Movement":"transfer relocation",
  "User":"agent requester person employee people",
  "Task":"todo subtask activity",
  "Deployment":"deploy rollout",
};
const moduleSearchStr = (m) => (m + " " + (MODULE_SYNONYMS[m] || "")).toLowerCase();
const moduleArticle = (name) => { const n=(name||"").trim();
  if (/^(user|uni|eu|one)/i.test(n)) return "a"; return /^[aeiou]/i.test(n) ? "an" : "a"; };
// TOKEN search — the ONE matcher for every search box in the app. Split the query into WORDS; an item matches
// when EVERY word is a substring of its haystack (word order & gaps don't matter), so "add task" finds
// "Add a task" and "update priority" finds "set the priority". Empty query → matches. This is why searches feel
// usable: you no longer have to type the exact contiguous phrase.
const queryTokens = (q) => (q||"").toLowerCase().trim().split(/\s+/).filter(Boolean);
const tokenMatch = (hay, q) => { const toks = queryTokens(q); if (!toks.length) return true;
  const h = (hay||"").toLowerCase(); return toks.every(t => h.includes(t)); };
// Search match rendering. User 2026-07-10: "no need to highlight this much" — the query in the box is enough
// context, so matched text is rendered PLAIN (no marker). Kept as a passthrough so every call site stays valid;
// to bring the Ctrl+F yellow-marker back, restore the token-range version (git/history) — `--find-hl` still exists.
const hlMatch = (text, q) => text;
// verbs that a MODULE-forward row (matchOnly) treats as "free" — so "create" / "cre" alone shows only the generic
// "Create record", but "create task" / "task" / "new incident" surface the per-module row.
const CREATE_VERBS = ["create","creates","new","add","make","generate","a","an","record","records"];
// Popover search matcher (token-based). A `matchOnly` row matches only its own string: the query's NON-verb words
// must all be in it, and there must be at least one non-verb word (so a bare verb never explodes into every module).
const popMatch = (i, qq) => {
  if (i.header) return true;
  const toks = queryTokens(qq); if (!toks.length) return true;
  if (i.matchOnly != null) {
    const verbs = i.matchVerbs || [];
    const specific = toks.filter(t => !verbs.includes(t));
    if (!specific.length) return false;
    const mo = i.matchOnly.toLowerCase();
    return specific.every(t => mo.includes(t));
  }
  // NB: `sub` (the description line) is deliberately NOT searched — matching a row via its subtext (and then
  // highlighting a word there while the visible LABEL doesn't match) reads as confusing, not helpful (user 2026-07-10).
  const hay = [i.label, i.keywords, i.crumb].filter(Boolean).join(" ");
  return tokenMatch(hay, qq);
};
// Resolve a search string to a SECTION-WISE morph, or null (→ the normal menu/filter runs). For each matched
// module we emit an "Event Trigger › <Module>" section header + its create/update/archive rows (user 2026-07-10:
// "instead of radio, go section-wise — show it three times but with better context"). Returns { rows:[...] }.
function moduleMorphFor(raw) {
  const s = (raw||"").toLowerCase().trim();
  if (!s) return null;
  const tokens = s.split(/\s+/).filter(Boolean);
  // pull ONE event token out — but only when another token remains, so a bare "created" still browses.
  let eventFilter = null; const modToks = [];
  tokens.forEach(t => {
    const ev = tokens.length>1 && !eventFilter && TRIGGER_EVENTS.find(e=>e.verbs.includes(t));
    if (ev) eventFilter = ev.id; else modToks.push(t);
  });
  const mq = modToks.join(" ").trim();
  if (!mq) return null;                                   // only an event word typed → let the normal filter handle it
  const events = eventFilter ? TRIGGER_EVENTS.filter(e=>e.id===eventFilter) : TRIGGER_EVENTS;
  // resolve the ORDERED set of matching modules
  let modules;
  const fam = MODULE_FAMILIES.find(f => mq.length>=f.min && f.aliases.some(a => a.startsWith(mq)));
  if (fam) modules = fam.options.map(o=>o.module);          // curated family order (asset → Hardware/Software/Non-IT)
  else {
    const all = TRIGGER_MODULES; // trigger search also finds the combined "Request"
    const pref = all.filter(m => m.toLowerCase().startsWith(mq));           // prefix wins…
    const sub  = all.filter(m => !m.toLowerCase().startsWith(mq) && m.toLowerCase().includes(mq)); // …then substring…
    const syn  = all.filter(m => !m.toLowerCase().includes(mq) && (MODULE_SYNONYMS[m]||"").toLowerCase().split(/\s+/).some(x=>x && x.includes(mq))); // …then synonym ("ticket"→Incident)
    modules = pref.length ? pref : (sub.length ? sub : syn);
    if (!modules.length) return null;                        // no module → normal filter (finds the time-based rows)
    if (modules.length > 1 && (mq.length < 2 || modules.length > 5)) return null; // 1-char / broad → just browse
  }
  // build a section (header + event rows) per module. Row ids are module-qualified so 3× "created" don't collide;
  // `typeId` carries the actual trigger type for onPick.
  const rows = [];
  modules.forEach((module, mi) => {
    // section header = a plain BREADCRUMB (user 2026-07-10): "Event Trigger ›" stays faint, the MODULE is the
    // white hero. A divider AFTER each section (except the last — the footer border closes that one) so the
    // groups read clearly.
    rows.push({ header:"Event Trigger › "+module, headerNode:(
      <span><span style={{color:"var(--faint)"}}>Event Trigger › </span><span style={{color:"var(--accent2)", fontWeight:600}}>{module}</span></span>) });
    events.forEach(e => rows.push({
      id:module+":"+e.id, typeId:e.id, module, icon:e.icon, help:TRIGGER_HELP[e.id],
      label:`When ${moduleArticle(module)} ${module} ${e.tail}`,
      labelNode:<>When {moduleArticle(module)} {module} {e.tail}</>,
    }));
    if (mi < modules.length-1) rows.push({ divider:true });
  });
  return { rows };
}
// values offered when a particular field is chosen (for "field changes to a value")
const FIELD_VALUES = {
  priority:["Urgent","High","Medium","Low"],
  status:["New","In Progress","On Hold","Resolved","Closed"],
  category:["Hardware","Software","Network","Access","Email","Other"],
  impact:["High","Medium","Low"],
  urgency:["High","Medium","Low"],
  assignee:["Auto (round-robin)","Least busy","On-call agent","Specific agent…"],
  "assignment group":["Service Desk","Tier-2","Network Ops","Apps Team","Field Support"],
};

// Trigger "a {module}'s {field} is updated" — the FIELD list is MODULE-AWARE (was one generic TFIELDS list for
// every module): it mirrors the GET/condition catalog for the SELECTED module (so a Service Request shows Service-
// Request fields, an asset shows asset fields, etc. — "based on the record, not others"). Shape matches TFIELDS
// ({id,label,input,values}); input:"dropdown" enables the from→to value chain, everything else = plain "is updated".
// The module's GET-preset field (service catalog / asset type) is EXCLUDED — service catalog isn't a trigger field
// (it lives on the Get + in a Service-Request condition). (getPreset/conditionFieldsFor resolved at call time.)
function triggerFieldsFor(module){
  const toTrig = (f) => ({ id:f.id, label:f.label, input:(f.type==="enum"||f.type==="user") ? "dropdown" : (f.type==="text" ? "text" : "other"), values:f.values||[] });
  // exclude every relevant GET-preset field from the trigger's changed-field list (service catalog / asset type
  // aren't "updated" trigger fields). For a COMBINED module (Request) that means the presets of BOTH record types.
  const excl = new Set(); const p0 = getPreset(module); if (p0) excl.add(p0.field);
  const rm = moduleByLabel(module); (rm && rm.recordTypes ? rm.recordTypes : []).forEach(rt => { const p = getPreset(rt); if (p) excl.add(p.field); });
  return conditionFieldsFor(module).map(toTrig).filter(f => !excl.has(f.id));
}
// Returns the sentence template + an ORDERED list of slots ({key, options}) given current vals.
// options is an array, or "__date" / "__time" for native inputs.
function triggerView(trigger) {
  const v = trigger.vals, id = trigger.typeId;
  if (id==="created")  return { tpl:"a {module} is created",  slots:[{key:"module",options:TRIGGER_MODULES}] };
  if (id==="archived") return { tpl:"a {module} is archived", slots:[{key:"module",options:TRIGGER_MODULES}] };
  if (id==="changed") {
    const fields = triggerFieldsFor(v.module);      // module-aware field list (SR → SR fields; service catalog excluded — it's a condition/Get field)
    const fld = fields.find(f=>f.id===v.field);
    if (fld && fld.input==="dropdown") {            // dropdown → offer the from→to value chain
      const vals = fld.values || [];
      return { tpl:"a {module}'s {field} is updated from {from} to {to}",
        slots:[{key:"module",options:TRIGGER_MODULES},{key:"field",options:fields},
               {key:"from",options:["any",...vals]},{key:"to",options:vals.filter(x=>x!==v.from)}] };
    }
    return { tpl:"a {module}'s {field} is updated",      // text / date / number / etc. → just "is updated"
      slots:[{key:"module",options:TRIGGER_MODULES},{key:"field",options:fields}] };
  }
  // time-based triggers (2026-07-10 rework): five clear cadences, each a PROPER sentence (replaces the old
  // "date is reached" + nested "every time period" cadence picker). Once has a date AND time.
  if (id==="once")    return { tpl:"Once on {date} at {time}",              slots:[{key:"date",options:"__date"},{key:"time",options:"__time"}] };
  if (id==="hourly")  return { tpl:"Every hour",                            slots:[] };
  if (id==="daily")   return { tpl:"Every day at {time}",                   slots:[{key:"time",options:"__time"}] };
  if (id==="weekly")  return { tpl:"Every week on {weekday} at {time}",     slots:[{key:"weekday",options:WEEKDAYS},{key:"time",options:"__time"}] };
  if (id==="monthly") return { tpl:"Every month on day {dom} at {time}",    slots:[{key:"dom",options:DOM},{key:"time",options:"__time"}] };
  // LEGACY (no longer creatable from the menu, kept so old seeded docs still render): date_reached + periodically
  if (id==="date_reached") return { tpl:"{date} is reached", slots:[{key:"date",options:"__date"}] };
  // periodically — chain depends on the cadence
  const c = v.cadence, base = [{key:"cadence",options:CADENCE}];
  if (c==="daily")    return { tpl:"{cadence} at {time}", slots:[...base,{key:"time",options:"__time"}] };
  if (c==="weekly")   return { tpl:"{cadence} on {weekday} at {time}", slots:[...base,{key:"weekday",options:WEEKDAYS},{key:"time",options:"__time"}] };
  if (c==="monthly")  return { tpl:"{cadence} on day {dom} at {time}", slots:[...base,{key:"dom",options:DOM},{key:"time",options:"__time"}] };
  if (c==="on a specific date") return { tpl:"{cadence} — {date} at {time}", slots:[...base,{key:"date",options:"__date"},{key:"time",options:"__time"}] };
  return { tpl:"{cadence}", slots:base };
}

// Each field has a TYPE that decides its operators and value input:
//   enum   -> operators is/is not/is one of, value = dropdown of `values`
//   text   -> operators contains/starts with/…, value = free text input
//   number -> operators is/greater than/…, value = number input
//   date   -> operators is on/before/after, value = date input
const FIELDS = [
  // priority & impact
  { id:"priority", label:"priority", type:"enum", values:["Urgent","High","Medium","Low"] },
  { id:"impact", label:"impact", type:"enum", values:["High","Medium","Low"] },
  { id:"urgency", label:"urgency", type:"enum", values:["High","Medium","Low"] },
  // classification
  { id:"status", label:"status", type:"enum", values:["New","Assigned","In Progress","On Hold","Pending","Resolved","Closed","Cancelled"] },
  { id:"category", label:"category", type:"enum", values:["Hardware","Software","Network","Access","Access Management","Email","Database","Security","Other"] },
  { id:"subcategory", label:"subcategory", type:"enum", values:["Laptop","Desktop","Server","VPN","Wi-Fi","Login / Password","Password Reset","Mailbox","Application","Other"] },
  { id:"channel", label:"source channel", type:"enum", values:["Email","Self-Service Portal","Phone","Chat","Walk-up","API","Monitoring alert"] },
  // free text
  { id:"subject", label:"subject", type:"text" },
  { id:"description", label:"description", type:"text" },
  // assignment
  { id:"group", label:"assignment group", type:"enum", values:["Service Desk","Tier-2","Tier-3","Network Ops","Apps Team","Field Support","Security","Database"] },
  { id:"assignee", label:"assignee", type:"enum", values:["Unassigned","Current user","On-call agent","A specific agent…"] },
  { id:"vip", label:"the requester", type:"enum", values:["a VIP","not a VIP"] },
  { id:"requester_dept", label:"requester's department", type:"enum", values:["IT","Finance","HR","Sales","Operations","Executive"] },
  { id:"requester_email", label:"requester's email", type:"text" },
  // SLA & timing
  { id:"sla", label:"SLA status", type:"enum", values:["Within SLA","At risk","Breached","Paused"] },
  { id:"hours", label:"time window", type:"enum", values:["business hours","after hours","weekend","holiday"] },
  { id:"reopen", label:"reopen count", type:"number" },
  { id:"age", label:"hours open", type:"number" },
  { id:"due", label:"due date", type:"date" },
  // change
  { id:"change_type", label:"change type", type:"enum", values:["Standard","Normal","Emergency"] },
  { id:"change_risk", label:"change risk", type:"enum", values:["High","Medium","Low"] },
  { id:"approval", label:"approval status", type:"enum", values:["Pending","Approved","Rejected","Not required"] },
  // problem & CMDB
  { id:"known_error", label:"known error", type:"enum", values:["Yes","No"] },
  { id:"ci", label:"affected CI / service", type:"enum", values:["Email Service","Payroll App","VPN Gateway","CRM","Database Cluster","Web Portal","Active Directory"] },
  { id:"ci_env", label:"CI environment", type:"enum", values:["Production","Staging","Development","DR"] },
  { id:"service_tier", label:"service tier", type:"enum", values:["Tier 1 (critical)","Tier 2","Tier 3"] },
  // tags — multi-value (pick several)
  { id:"tag", label:"a tag", type:"enum", values:["major","vip","recurring","needs-review","after-hours","security"] },
  { id:"tags", label:"tags", type:"enum", multi:true, values:["major","vip","recurring","needs-review","after-hours","security","escalated","monitoring","compliance"] },
  { id:"watchers", label:"watchers", type:"enum", multi:true, values:["Service Desk","Network Ops","Security","Apps Team","On-call agent","Requester's manager"] },
];
const fieldDef = (id) => FIELDS.find(f=>f.id===id);

// operators per field type. Date supports FIXED-date compares AND relative ones (value = a duration).
const TYPE_OPS = {
  enum:   ["is","is not","is one of"],
  select: ["is","is not"], // single-select enum (value picker offers exactly one) — no "is one of"
  text:   ["contains","does not contain","must contain","is","is not","starts with","ends with"],
  number: ["is","is not","is greater than","is less than","is at least","is at most"],
  date:   ["is on","is before","is after","is within the next","is within the last"],
};
// operators available for a FIELD (not just its type): base type ops, PLUS "must contain" for
// multi-value SET fields (tags/watchers — type "enum" with multi:true). Single enums stay unchanged.
// Shared by every operator picker (Condition inline+branch, GET "where", WAIT "until", form conditions).
const opsFor = (f) => { const base = TYPE_OPS[f?.type] || TYPE_OPS.enum; return (f && f.multi && !base.includes("must contain")) ? [...base, "must contain"] : base; };
// date ops whose value is a relative DURATION (e.g. "30 days"), not a fixed date
const REL_DATE_OPS = ["is within the next","is within the last"];
const isRelDateOp = (op) => REL_DATE_OPS.includes(op);
const REL_DATE_UNITS = ["hours","days","weeks","months","years"]; // relative value = a number + a unit
const defaultOp = (type) => ({ enum:"is", text:"contains", number:"is", date:"is on" }[type] || "is");
const valuePlaceholder = (type) => ({ text:"some text", number:"a number", date:"a date" }[type] || "a value");
// A smart value (dynamic) is stored as an object on clause.value: {ref:…} (reference) or {expr:…} (expression).
// smartKindOf → "ref" | "expr" | null; the sentence renders a smart value as a neutral editable BADGE, not a slot.
const smartKindOf = (v) => (v && typeof v==="object" && !Array.isArray(v)) ? (v.ref ? "ref" : (v.expr!=null ? "expr" : null)) : null;

// ── shared inline glyphs (kept in ONE place so every usage stays consistent) ─────────────────────────
// FX_GLYPH: the spreadsheet-style function symbol — an italic "f" followed by a small "x".
// BRACES_GLYPH: a curly-braces "{ }" symbol for References (mirrors the #{…} reference syntax).
const FxGlyph = () => <span style={{fontStyle:"italic"}}>f<span style={{fontStyle:"normal", fontSize:"0.72em"}}>x</span></span>;
const BracesGlyph = () => <span style={{fontWeight:600, letterSpacing:"-0.04em"}}>{"{ }"}</span>;
// AI "sparkle" glyph — a big 4-point star + a small one; marks the "set automatically using AI" (Smart Suggestion) value.
const AiSparkle = (props) => <svg width="15" height="15" viewBox="0 0 24 24" fill="none" {...props}><path d="M12 2.5l1.7 4.9 4.9 1.7-4.9 1.7L12 15.7l-1.7-4.9-4.9-1.7 4.9-1.7L12 2.5z" fill="currentColor"/><path d="M18.5 14l.85 2.15L21.5 17l-2.15.85L18.5 20l-.85-2.15L15.5 17l2.15-.85L18.5 14z" fill="currentColor" opacity="0.75"/></svg>;

// ── EXPRESSION BUILDER catalog (smart value → Expression) ───────────────────────────────────────────
// AUTHORITATIVE — extracted verbatim from Workflow_Expression_Reference.xlsx (String/Date/Math functions
// + Comparison/Logical/Arithmetic operators). Do NOT hand-edit; regenerate from the sheet if it changes.
