function conditionFieldsFor(mod){
  const m = (mod||"").toLowerCase();
  if (m.includes("problem")) return PROBLEM_COND;
  if (m.includes("change")) return CHANGE_COND;
  if (m.includes("release")) return RELEASE_COND;
  if (m.includes("cmdb")) return CMDB_COND;
  if (m.includes("asset")) return ASSET_COND; // hardware / software / non-it
  if (m.includes("movement")) return ASSET_MOVEMENT_COND;
  if (m.includes("user")) return USER_COND;
  if (m.includes("task")) return TASK_COND;
  if (m.includes("announce")) return ANNOUNCEMENT_COND;
  if (m.includes("deployment")) return DEPLOYMENT_COND;
  if (m.includes("service request")) return SERVICE_REQUEST_COND; // SR = request set + service catalog (Incident has none)
  if (m.includes("request")) return REQUEST_COMBINED_COND; // "Request" (combined) = Incident ∪ Service Request
  return REQUEST_COND; // Incident, default
}

// Build the action catalog (flat defs + categorized menu) for a given record-module id.
function actionCatalogFor(mid) {
  const m = moduleDef(mid);
  const label = m ? m.label : "record";
  const recs  = RECIPIENTS[mid] || RECIPIENTS_BASE;
  const chans = channelsFor(mid);
  // "create a new {record}" — any record type is creatable, not just the trigger's module.
  // menuLabel = how it reads in the action picker; label = the in-sentence verb (slot fills the type).
  // Deployment is excluded here — it has its own Create deployment action (source record + packages drawer, v8).
  // Announcement too — its own Create announcement action + form; Asset Movement can't be created (user 2026-10-12).
  const recordOps = [{ id:"create", label:"create a new", menuLabel:"Create record", arg:MODULE_NAMES.filter(x=>!["Deployment","Announcement","Asset Movement"].includes(x)), argPlaceholder:"record", icon:I.plus, details:true }];
  const defs = [
    // Record operations (§4.1)
    ...recordOps,
    { id:"update",   label:"update the record", icon:I.field, details:true },
    { id:"close",    label:"close the record", icon:I.flag },
    { id:"archive",  label:"archive the record", icon:I.trash },
    { id:"get",      label:"get a record from", arg:RECORD_MODULES.map(x=>x.label), icon:I.field },
    { id:"get_many", label:"get many records from", arg:RECORD_MODULES.map(x=>x.label), icon:I.field },
    // Assignment — the most common, user-facing action ("assign it to {user/group}")
    { id:"assign", label:"assign it to", arg:ASSIGN_TARGETS, argPlaceholder:"user/group", icon:I.user },
    { id:"set_auto_assignment", label:"set auto assignment using", arg:["Round Robin","Smart Balance"], argPlaceholder:"method", icon:I.user },
    // Cross-module (§4.2)
    { id:"execute_integration", label:"execute integration", arg:Object.keys(APP_INTEGRATIONS), argPlaceholder:"an app", icon:I.link }, // v8: "for {record}, in {app} execute {integration}" + input mappings (drawer)
    { id:"add_relation", label:"add a relation", icon:I.link },
    { id:"add_task",     label:"add a task", icon:I.task, details:true }, // v8: field-row drawer (locked start date + subject)
    { id:"create_deployment", label:"create a Deployment", menuLabel:"Create deployment", icon:I.box },
    { id:"create_announcement", label:"create an Announcement", menuLabel:"Create announcement", icon:I.bell },
    // Communication (§4.3) — one action per channel, recipient is a module-gated arg
    ...chans.map(ch => ({ id:`send_${ch.toLowerCase().replace(/\s+/g,"_")}`, label:`send ${ch} to`, arg:recs, icon:ch==="Email"?I.mail:I.bell })),
    { id:"send_approval_reminder", label:"send an approval-reminder email to", arg:recs, icon:I.mail },
    // node-first placeholder: "Send notification" adds THIS action instantly; picking a channel on the
    // canvas then swaps it to the concrete send_* id (2026-07-03 — the fewer-steps flow). No arg, no form.
    { id:"send_notification", label:"send a notification", icon:I.bell },
    // Module-specific (§4.4)
    ...(MODULE_ACTIONS[mid] || []).map(a=>({ ...a, icon:a.icon||I.flag })),
    // Functional areas (available to any workflow)
    { id:"run_approval", label:"run approval workflow", icon:I.status },
    { id:"ask_approval", label:"ask for Approval", icon:I.status },
    { id:"request_signature", label:"request Signature", icon:I.status }, // EMBED (node-based parity): Request Signature — record in the sentence, template in the drawer
    { id:"http_request", label:"make an HTTP request / webhook", icon:I.up },
    { id:"run_plugin",   label:"run a Plugin", icon:I.repeat },
  ];
  const byId = Object.fromEntries(defs.map(d=>[d.id, d]));
  const has = (...ids) => ids.filter(id=>byId[id]).map(id=>({ id, label:byId[id].menuLabel || byId[id].label, icon:byId[id].icon }));
  const menu = [
    { header:"Assignment" }, ...has("assign","set_auto_assignment"),
    { header:"Record operations" }, ...has("create","create_deployment","create_announcement","update","archive","get","get_many"),
    { header:"Cross-module" }, ...has("execute_integration","add_relation","add_task"),
    { header:"Communication" }, ...has(...chans.map(ch=>`send_${ch.toLowerCase().replace(/\s+/g,"_")}`), "send_approval_reminder"),
    ...((MODULE_ACTIONS[mid]||[]).length ? [{ header:`${label}-specific` }, ...has(...(MODULE_ACTIONS[mid]||[]).map(a=>a.id))] : []),
    { header:"Approval, HTTP & plugins" }, ...has("run_approval","ask_approval","request_signature","http_request","run_plugin"),
  ];
  return { defs, byId, menu };
}

// Action menu = GROUPED for browsing (few top-level choices) + FLAT for search (type a term like
// "sync rule" / "webhook" / "block user" and jump straight to it). Each leaf maps to an action id in
// the per-module catalog (a leaf only appears if its id exists for the current module). `editor:"form"`
// leaves open a form panel (built later); others use inline slots.
// `section` groups the categories in the MAIN menu (super-headers). `sub` (on leaves) sub-categorizes a
// group's sub-menu (e.g. Update → Manual / Automatic) — only set it where a split actually helps.
const ACTION_GROUPS = [
  { id:"create",  label:"Create",            section:"Record management", leaves:[ {a:"create", label:"Create record", kw:"create new add record"}, {a:"create_deployment", label:"Create deployment", kw:"deployment deploy package install uninstall rollout software"}, {a:"create_announcement", label:"Create announcement", kw:"announcement announce broadcast notice portal"} ] },
  // `direct` (2026-07-03 fewer-steps): Update adds the manual field-update node INSTANTLY (drawer opens
  // right away); the Automatic variants (Priority Matrix / Smart Suggestion) stay findable via search.
  { id:"update",  label:"Update record",     section:"Record management", direct:{ a:"update", label:"Update record", kw:"update set edit modify change field status priority category subcategory assignee group impact urgency sla value" },
    leaves:[ {a:"update", label:"Update record field", kw:"update set edit modify change field status priority category subcategory assignee group impact urgency sla value", sub:"Manual", _noHow:true} ] },
  // standalone steps, as in the node-based builder (v8, user 2026-10-13) — no longer values inside Update record
  { id:"auto_set", label:"Set automatically", section:"Record management", leaves:[ {a:"priority_matrix", label:"Set priority as per Priority Matrix", kw:"priority matrix set update automatic"}, {a:"smart_suggestion", label:"Set suggested field by Smart Suggestion", kw:"smart suggestion ai auto category update automatic"} ] },
  { id:"assign",  label:"Assign",            section:"Record management", leaves:[ {a:"assign", label:"Assign record", kw:"assign user group technician team auto assignment round robin smart balance"} ] },
  { id:"close",   label:"Close record",      section:"Record management", direct:{ a:"close", label:"Close record", kw:"close resolve finish complete done ticket request incident" },
    leaves:[ {a:"close", label:"Close this record", kw:"close resolve finish complete done ticket request incident"}, {a:"close_related_requests", label:"Close all related Requests", kw:"close related request ticket"}, {a:"close_related_problems", label:"Close all related Problems", kw:"close related problem"} ] },
  { id:"archive", label:"Archive",           section:"Record management", leaves:[ {a:"archive", label:"Archive record", kw:"archive record"} ] },
  { id:"link",    label:"Link & add",        section:"Record management", leaves:[ {a:"add_task", label:"Add a task", kw:"task add subtask"}, {a:"add_relation", label:"Add a relation", kw:"relation relate link"}, {a:"add_barcode", label:"Add a barcode", kw:"barcode asset"} ] },
  // `direct` = node-first (2026-07-03): the menu row ADDS this placeholder action immediately (no channel
  // sub-menu drill) — the channel picker then opens ON THE CANVAS sentence. The leaves stay for flat
  // SEARCH ("email" still jumps straight to a preset channel) and for availability gating.
  { id:"notify",  label:"Send notification", section:"Communicate", direct:{ a:"send_notification", label:"Send notification", kw:"notify notification send message" },
    leaves:[ {a:"send_email", label:"via Email", kw:"email notify send mail"}, {a:"send_sms", label:"via SMS", kw:"sms text notify"}, {a:"send_whatsapp", label:"via WhatsApp", kw:"whatsapp notify"}, {a:"send_teams", label:"via Teams", kw:"teams notify"}, {a:"send_google_chat", label:"via Google Chat", kw:"google chat notify"} ] }, // (Approval reminder = an email TEMPLATE, deliberately NOT a leaf/channel)
  { id:"exec",    label:"Execute plugin or app integration", section:"Automate & integrate", leaves:[ {a:"run_plugin", label:"Execute plugin", kw:"plugin run execute", editor:"form"}, {a:"execute_integration", label:"Execute app integration", kw:"integration app execute"}, {a:"sync_rule", label:"Execute Sync Rule", kw:"sync rule execute"}, {a:"warranty_sync", label:"Execute Warranty Sync", kw:"warranty sync"} ] },
  { id:"webhook", label:"Run webhook (HTTP)", section:"Automate & integrate", leaves:[ {a:"http_request", label:"Run webhook (HTTP)", kw:"webhook http request api rest"} ] },
  { id:"approval_run", label:"Run approval workflow", section:"Approval", leaves:[ {a:"run_approval", label:"Run approval workflow", kw:"approval workflow run"} ] },
  { id:"approval_ask", label:"Ask for approval",      section:"Approval", leaves:[ {a:"ask_approval", label:"Ask for approval", kw:"approval ask request", editor:"form"} ] },
  { id:"signature_req", label:"Request signature",    section:"Approval", leaves:[ {a:"request_signature", label:"Request signature", kw:"signature sign digital esign e-sign template", editor:"form"} ] },
  { id:"user",    label:"User management",   section:"Users", leaves:[ {a:"block_user", label:"Block user", kw:"block user disable"}, {a:"unblock_user", label:"Unblock user", kw:"unblock user enable"}, {a:"convert_requester", label:"Convert to Requester", kw:"convert requester"}, {a:"convert_technician", label:"Convert to Technician", kw:"convert technician"} ] },
];

