      if (d.duration){ s.push({t:"for"}); s.push({t:d.duration+" "+(d.duration_unit||"Hours").toLowerCase(),em:true}); }
      const on=[d.support_portal && "support portal", d.tech_portal && "technician portal"].filter(Boolean);
      if (on.length){ s.push({t:"on the"}); s.push({t:on.join(" and "),em:true}); }
