        {confirm==="strip" ? confirmBar("Clear all", vals.length, ()=>onChange(null)) : <span className="flex items-center gap-3">{allChips && plainBtn("Show less", ()=>setAllChips(false), "var(--accent2)")}{plainBtn("Clear all", ()=>setConfirm("strip"))}</span>}
