// shared help card (graphic + friendly text). `compact` = small icon tile on the LEFT + title beside it,
// description below (used in the rail Quick Help). Default = big graphic banner (badge tooltip).
function HelpCard({ help, compact }) {
  if (!help) return null;
  if (compact) {
    return (
      <div>
        <div className="flex items-center gap-2.5 mb-2">
          {help.graphic && (
            <span className="w-9 h-9 rounded-lg flex items-center justify-center shrink-0" style={{ background:help.bg||"var(--panel2)", color:help.color||"var(--text)" }}>{help.graphic}</span>
          )}
          <div className="min-w-0">
            {help.eyebrow && <div className="text-[9px] font-semibold uppercase tracking-[0.13em] flex items-center gap-1" style={{color:help.color||"var(--muted)", opacity:.75}}>{help.eyebrow}<span style={{opacity:.6}}>›</span></div>}
            <div className="text-[length:var(--fs-14)] font-semibold leading-tight" style={{color:help.color||"var(--text)"}}>{help.title}</div>
          </div>
        </div>
        <div className="text-[length:var(--fs-125)] leading-relaxed" style={{color:"var(--muted)"}}>{help.body}</div>
        {help.eg && <div className="text-[length:var(--fs-115)] italic mt-1.5 leading-snug" style={{color:"var(--faint)"}}>{help.eg}</div>}
      </div>
    );
  }
  return (
    <div>
      {/* optional eyebrow breadcrumb (e.g. "CONDITION ›") so you feel you've descended into a category */}
      {help.eyebrow && <div className="text-[length:var(--fs-10)] font-semibold uppercase tracking-[0.13em] mb-1 flex items-center gap-1" style={{color:help.color||"var(--muted)", opacity:.75}}>{help.eyebrow}<span style={{opacity:.6}}>›</span></div>}
      {/* heading */}
      <div className="text-[length:var(--fs-14)] font-semibold mb-2.5" style={{color:help.color||"var(--text)"}}>{help.title}</div>
      {/* full-width graphic banner (excludes the card padding) */}
      {help.graphic && (
        <div className="w-full rounded-xl flex items-center justify-center mb-3" style={{ height:"92px", background:help.bg||"var(--panel)", color:help.color||"var(--text)", overflow:"hidden" }}>
          <span style={{ transform:"scale(2.1)" }}>{help.graphic}</span>
        </div>
      )}
      {/* description */}
      <div className="text-[length:var(--fs-125)] leading-relaxed" style={{color:"var(--muted)"}}>{help.body}</div>
      {help.eg && <div className="text-[length:var(--fs-115)] italic mt-1.5 leading-snug" style={{color:"var(--faint)"}}>{help.eg}</div>}
    </div>
  );
}

/* ---------------------------------------------------------------------------
   "How it works" stepper — illustrative builder mockups (div/badge graphics).
   Each step renders a glassmorphism frosted card showing the builder at a stage.
--------------------------------------------------------------------------- */
// a small role-badge row used inside the stepper mockups (a mini builder card)
function MockRow({ badge, rc, bg, icon, text, ghost, highlight, dim }) {
  return (
    <div className="flex items-center gap-2.5 rounded-xl px-3 py-2"
      style={{
        background: ghost ? "transparent" : "var(--pop-bg)",
        border: highlight ? `1.5px solid ${rc}` : "1px solid var(--border)",
        boxShadow: highlight ? `0 0 0 4px color-mix(in srgb, ${rc} 16%, transparent)` : "none",
        borderStyle: ghost ? "dashed" : "solid",
        opacity: dim ? 0.6 : 1,
      }}>
      <span className="w-6 h-6 shrink-0 rounded-md flex items-center justify-center" style={{ background:bg, color:rc }}>{icon}</span>
      <div className="min-w-0 text-left flex-1">
        <div className="text-[8px] font-semibold uppercase tracking-[0.14em]" style={{color:rc}}>{badge}</div>
        <div className="text-[length:var(--fs-11)] leading-snug truncate" style={{color: ghost ? "var(--faint)" : "var(--text)"}}>{text}</div>
      </div>
    </div>
  );
}
// a tiny rail dot, like the vertical rail in the real builder
const RailDot = ({ rc }) => (
  <span className="shrink-0 w-2 h-2 rounded-full" style={{ background: rc || "var(--border2)", boxShadow: rc ? `0 0 0 3px color-mix(in srgb, ${rc} 22%, transparent)` : "none" }} />
);
// a row option inside a floating popover (icon + label, optional highlight / soon)
function PopOption({ rc, bg, icon, label, sub, highlight, soon }) {
  return (
    <div className="flex items-center gap-2 rounded-lg px-2 py-1.5"
      style={{ background: highlight ? "var(--pop-hover)" : "transparent", opacity: soon ? 0.45 : 1 }}>
      <span className="w-5 h-5 shrink-0 rounded-md flex items-center justify-center" style={{ background:bg, color:rc }}>{icon}</span>
      <div className="min-w-0 flex-1">
        <div className="text-[length:var(--fs-105)] leading-tight truncate" style={{color:"var(--text)"}}>{label}</div>
        {sub && <div className="text-[8.5px] leading-tight truncate" style={{color:"var(--faint)"}}>{sub}</div>}
      </div>
      {soon && <span className="text-[7.5px] font-semibold uppercase tracking-wide px-1 py-0.5 rounded" style={{background:"var(--panel)", color:"var(--faint)", border:"1px solid var(--border)"}}>soon</span>}
    </div>
  );
}
// a small frosted popover anchored inside the mock scene
const MockPop = ({ children, style }) => (
  <div className="glass rounded-xl p-1.5 flex flex-col gap-0.5"
    style={{ width: 180, ...style }}>{children}</div>
);

