function Kbd({ children }) {
  return <kbd className="px-1.5 py-0.5 rounded text-[length:var(--fs-micro)] font-medium leading-none"
    style={{ background:"var(--panel2)", border:"1px solid var(--border)", color:"var(--muted)", fontFamily:"inherit" }}>{children}</kbd>;
}
