  if (/priority/.test(f)) return "High"; if (/status/.test(f)) return "Open"; if (/urgency|impact/.test(f)) return "Medium";
  if (/email/.test(f)) return "jane.cooper@acme.com"; if (/phone|mobile/.test(f)) return "+1 555 0100";
  if (/name|requester|assignee|technician|manager|owner|user|by$/.test(f)) return "Jane Cooper";
  if (/\bid\b|number|count|no\.?$/.test(f)) return 1042; if (/subject|title/.test(f)) return "Laptop won't boot";
