  const [q, setQ] = useState("");
  const [sel, setSel] = useState(null);       // { kind:"fn"|"op", item }
  const ql = q.trim().toLowerCase();
  const fnMatch = (f)=> !ql || [f.name, f.display, f.desc, f.cat].some(x=>String(x||"").toLowerCase().includes(ql));
  const opMatch = (o)=> !ql || [o.name, o.display, o.desc, o.cat].some(x=>String(x||"").toLowerCase().includes(ql));
  const showFns = ql || tab!=="operators", showOps = ql || tab!=="functions";
  const groups = []; const addG = (kind, list)=>{ list.forEach(it=>{ let g = groups.find(x=>x.kind===kind && x.cat===it.cat); if (!g){ g = { kind, cat:it.cat, items:[] }; groups.push(g); } g.items.push(it); }); };
