    if (bp.length>=sp.length && sp.every((v,i)=>v===bp[i])) return f; // src is the branch or an ancestor of this lane
    const srcNode = nodeAt(f, sp); if(!srcNode || srcNode.kind==="branch") return f; // no whole branch inside a lane
    let t = treeRemove(f, sp);
