    const bn = nodeAt(t, bp2); if(!bn) return f;
    if (pi==="ow") { if(!bn.otherwise) return f; return treeUpdate(t, bp2, { otherwise: { ...bn.otherwise, children:[ ...(bn.otherwise.children||[]), srcNode ] } }); }
