  const dropInto = (branchId, e) => { if(e&&e.preventDefault)e.preventDefault(); const src=dragIdRef.current; if(src!=null) moveNode(src, {into:branchId}); setDropHint(null); dragIdRef.current=null; }; // kept for the branch-lane end zone
  // ── DRAG LOCKS (v5.11 Slice 2) — the validation rulebook. Two questions: (1) can this node be GRABBED at all
  //    (`nodeLocked` → no grip); (2) is a given drop legal (`dropAllowed` → hit-test skips it). ──
  const isPeriodicTrigger = () => { const t = triggers[0]; return !!(t && isPeriodicType(t.typeId)); };
  // the mandatory Get glued right under a periodic trigger = flow[0] when it's a Get (event triggers have no such glue)
  const periodicGetId = () => { const f = flowRef.current; return (isPeriodicTrigger() && f[0] && f[0].kind==="get") ? f[0].id : null; };
