        if (n.success){ const r=firstBranchDFS(n.success.children||[], [...p,{success:true}]); if(r) return r; }
        if (n.otherwise){ const r=firstBranchDFS(n.otherwise.children||[], [...p,{otherwise:true}]); if(r) return r; }
