      // (assignee = a field) so an Assign chip was redundant; Create is distinct and stays.
      const chips = [
        avail.has("send_notification") && { id:"pop:send_notification", label:"Notify", icon:I.bell, _leaf:{ a:"send_notification" } },
        avail.has("create") && { id:"pop:create", label:"Create", icon:I.plus, _leaf:{ a:"create" } },
        avail.has("update") && { id:"pop:update", label:"Update", icon:I.field, _leaf:{ a:"update" } },
      ].filter(Boolean);
