        if (i.id === "branching") { setPop(branchFirstStepMenuConfig(anchor, backHere, (step) => addBranchAndPick(parent, anchor, idx, step))); return true; }
        if (i.id === "delay") { addDelayAndPick(parent, anchor, idx); return; }
