    // sub-chooser keeps a branch preview) → restore its `realKids`; else strip a leftover single ghost by id.
    const sp = splitPreviewRef.current;
    const gidPrev = previewGhostRef.current;
    const cleanFlow = sp ? treeSetLevel(flowRef.current, sp.targetPath, sp.realKids)
      : gidPrev ? (()=>{ const p=treeFindPath(flowRef.current, gidPrev); return p ? treeRemove(flowRef.current, p) : flowRef.current; })()
      : flowRef.current;
