  const flatItems = (avail) => { const ls=actionLeafIndex(avail);
    const mk=(lf)=> lf.avail ? { id:"f:"+lf.a, label:lf.label, sub:lf.group, keywords:lf.kw, _leaf:lf, help:ACTION_HELP[lf.a] }
                             : { id:"fx:"+lf.a, label:lf.label, sub:lf.group, keywords:lf.kw, disabled:true, tag:"unavailable", hint:availHint([lf.a]), help:ACTION_HELP[lf.a] };
    return [...ls.filter(l=>l.avail).map(mk), ...ls.filter(l=>!l.avail).map(mk)]; };
