        if (g.direct) { return anyAvail ? { id:"leaf:"+g.direct.a, label:g.direct.label, _leaf:g.direct, _sec:g.section, help:ACTION_HELP[g.direct.a]||ACTION_HELP[g.id] } : { id:"gx:"+g.id, label:g.direct.label, disabled:true, tag:"unavailable", hint:availHint(total.map(l=>l.a)), _sec:g.section, help:ACTION_HELP[g.direct.a]||ACTION_HELP[g.id] }; }
        if (total.length===1) { const lf=total[0]; return leafAvail(lf, avail) ? { id:"leaf:"+lf.a, label:lf.label, _leaf:lf, _sec:g.section, help:ACTION_HELP[lf.a]||ACTION_HELP[g.id] } : { id:"gx:"+g.id, label:lf.label, disabled:true, tag:"unavailable", hint:availHint([lf.a]), _sec:g.section, help:ACTION_HELP[lf.a]||ACTION_HELP[g.id] }; }
        const ghelp = ACTION_HELP["grp_"+g.id] || ACTION_HELP[g.id];
