    const node = { id:nid(), kind:"action", action:leaf.a, arg: leaf._arg || null, ...(leaf.a==="set_auto_assignment"?{pool:"all", online:false}:{}) }; // _arg = level-3 preset value (e.g. "Smart Balance", "Slack", a create type)
