            const rmStage = (i2) => { setD("stages", dstages.filter((_,ix)=>ix!==i2)); reKey(was=>was.filter((_,ix)=>ix!==i2)); };
            const dupStage = (i2) => { const copy = JSON.parse(JSON.stringify(dstages[i2])); setD("stages", [...dstages.slice(0,i2+1), copy, ...dstages.slice(i2+1)]); reKey(was=>[...was.slice(0,i2+1), true, ...was.slice(i2+1)]); };
