                      const reveal = (k2)=> !!openSecs["cmp:"+dnode.id+":"+k2] || !!ddata[k2];   // keyed per node so email A's reveal doesn't leak into email B
                      const show = (k2)=> setOpenSecs(s2=>({...s2, ["cmp:"+dnode.id+":"+k2]:true}));
                      const revealCc = reveal("cc") || !!ccPre.length;                            // Cc collapses like Bcc (Gmail: quiet links inside the To row)
                      const pvKey = "cmp:"+dnode.id+":pv"; const pv = !!openSecs[pvKey];          // Edit ⇄ Preview (chips resolved against SAMPLE_PH)
